import React from 'react';
import Item from '../courses/CourseItem'; 
import './Courses.css';

const Courses = () => {
  const course = [
    {
        title: "MATH 101",
        courseTitle: "Differential Calculus with Applications", 
        desc: " " ,
    },
    {
        title: "MATH 100",
        desc: "..." ,
    },
    {
        title: "CPSC 110",
        desc: "..." ,
    },
    {
        title: "CPSC 121",
        desc: "..." ,
    },
    {
        title: "CPSC 210",
        desc: "..." ,
    },
    {
        title: "PHYS 119",
        desc: "..." ,
    },
    {
        title: "CHEM 121",
        desc: "..." ,
    },
    {
        title: "SCIE 113",
        desc: "..." ,
    },
    {
        title: "PHYS 106",
        desc: "..." ,
    },
    {
        title: "POLI 101",
        desc: "..." ,
    },
  ];

  return (
    <div className="course-container"> {}
      {course.map((c) => (
        <Item
          key={c.title}
          title={c.title}
          courseTitle={c.courseTitle}
          desc={c.desc}
        />
      ))}
    </div>
  );
};

export default Courses;
